const T=(id,title,instructions,starter,solution,checks,hint)=>({id,title,instructions:Array.isArray(instructions)?instructions:[instructions],prompt:Array.isArray(instructions)?instructions.join(' '):instructions,starter,solution,checks:checks.map(([label,test])=>({label,test})),hint,input:''});
const Q=(question,options,answer,why)=>({question,options,answer,why});
const prediction=(code,choices,correct,why)=>({code,question:'What is the output?',choices,correct,why,expected:choices[correct]+'\n'});
const P=(title,description,steps,starter,tests,extras,hint,plan)=>({title,description,steps,starter,tests,extras,hint,plan,input:''});
const C=(id,label,code,expected)=>({id,label,code,expected});
