 build:T('build','Add a Default','Write repeat(text, count=2). Return text repeated count times.','def repeat(text, count=2):\n    pass','def repeat(text, count=2):\n    return text * count',[['The default is used','repeat("ha") == "haha"'],['A keyword can replace it','repeat("x",count=3) == "xxx" and repeat("x",0) == ""']],'Multiplying a string by a non-negative integer repeats it.'),
 repair:T('repair','Avoid a Shared Default','Fix collect so calls without an items argument start with a fresh list.','def collect(value, items=[]):\n    items.append(value)\n    return items','def collect(value, items=None):\n    if items is None:\n        items = []\n    items.append(value)\n    return items',[['Default calls are independent','collect("a") == ["a"] and collect("b") == ["b"]'],['An explicit list is still used','collect("b",["a"]) == ["a","b"]']],'Use items=None, then if items is None: items = [].'),
 practice:[T('scale','Scale Without Changing Input','Write scaled(values, factor=2). Return a new list with every value multiplied by factor.','def scaled(values, factor=2):\n    pass','def scaled(values, factor=2):\n    return [value * factor for value in values]',[['Defaults and keyword arguments work','scaled([1,3]) == [2,6] and scaled([2],factor=3) == [6]'],['The original stays unchanged','(lambda data: scaled(data) == [4] and data == [2])([2])']],'Use a comprehension to create a new list.'),T('join','Create Labels','Write join_label(name, category="general"). Return category + ": " + name.','def join_label(name, category="general"):\n    pass','def join_label(name, category="general"):\n    return category + ": " + name',[['The default works','join_label("pen") == "general: pen"'],['Keyword calls work','join_label(category="art",name="brush") == "art: brush"']],'Keyword arguments may be given in a different order.')],
 homework:T('hw','Apply a Discount','Write discounted(prices, percent=10). Return a new list of prices after the percentage discount. Keep the inputs unchanged. Assume percent is from 0 to 100.','def discounted(prices, percent=10):\n    pass','def discounted(prices, percent=10):\n    return [price * (1 - percent / 100) for price in prices]',[['Default and custom discounts work','discounted([100,200]) == [90,180] and discounted([80],percent=25) == [60]'],['Boundary and empty inputs work','discounted([5],100) == [0] and discounted([],0) == []'],['The input is not changed','(lambda data: discounted(data) == [90] and data == [100])([100])']],'Calculate each new price using price * (1 - percent / 100).'),
 project:P('A Reusable Price Calculator','Write a small set of functions for an imaginary shop.',['Separate discount, total, and label calculations into helpers.','Use sensible default values and keyword calls.','Return results from helpers and print the final report separately.'],'prices = [20, 35, 10]\n# Define your helpers and produce a report.\n',['Call a helper twice with different arguments.','Try an empty price list and a zero discount.','Check that the original prices do not change.'],['Add a service fee as an optional argument.','Write docstrings describing the inputs and result.'],'Keep calculation separate from display.','What does each function receive and return?'),
 quiz:Q('When is a default list in def f(items=[]) created?',['Once, when the definition runs','Every time the function is called'],0,'The same default object is reused. None lets you choose when to create a fresh list.'),words:[['default argument','A value used when a caller omits an argument.'],['keyword argument','An argument supplied using its parameter name.'],['side effect','A change outside a function’s returned value.'],['local scope','Names available inside a particular function call.']],recap:['Use defaults and keywords to make calls clear.','Return results so callers can choose how to use them.','Avoid unintended changes to shared data.'],reflection:'Why does returning a new list make the discount function easier to reuse?'
