 build:T('build','Count Colours','Import Counter. Make counts for colours and print the count for blue.','colours = ["blue", "red", "blue"]\n# Import and use Counter.','from collections import Counter\ncolours = ["blue", "red", "blue"]\ncounts = Counter(colours)\nprint(counts["blue"])',[['All colours are counted','dict(counts) == {"blue":2,"red":1}'],['The blue count is printed','_output.strip() == "2"']],'Use Counter(colours), then look up "blue".'),
 repair:T('repair','Use the Module Name','math was imported as a module. Fix the call so 9 is square-rooted and printed.','import math\nprint(sqrt(9))','import math\nprint(math.sqrt(9))',[['The result is printed','_output.strip() == "3.0"']],'Use math.sqrt() after import math.'),
 practice:[T('average','Handle an Empty Average','Write average_or_none(values). Use statistics.mean for non-empty values and return None for an empty list.','import statistics\n\ndef average_or_none(values):\n    pass','import statistics\n\ndef average_or_none(values):\n    if not values:\n        return None\n    return statistics.mean(values)',[['Means are correct','average_or_none([2,4,6]) == 4 and average_or_none([1,2]) == 1.5'],['Empty input is explicit','average_or_none([]) is None']],'Check the list before calling mean().'),T('frequency','Return Word Counts','Write frequencies(words). Return a normal dictionary of counts using Counter.','from collections import Counter\n\ndef frequencies(words):\n    pass','from collections import Counter\n\ndef frequencies(words):\n    return dict(Counter(words))',[['Occurrences are counted','frequencies(["a","b","a"]) == {"a":2,"b":1}'],['Empty input works','frequencies([]) == {}']],'dict(Counter(words)) creates a normal dictionary from the counts.')],
 homework:T('hw','Find the Most Common Words','Write most_common_words(words). Return a sorted list of all words tied for the highest count. Empty input must give [].','from collections import Counter\n\ndef most_common_words(words):\n    pass','from collections import Counter\n\ndef most_common_words(words):\n    counts = Counter(words)\n    if not counts:\n        return []\n    highest = max(counts.values())\n    return sorted(word for word in counts if counts[word] == highest)',[['The most common word is found','most_common_words(["b","a","b"]) == ["b"]'],['Ties are kept and sorted','most_common_words(["b","a","b","a"]) == ["a","b"]'],['Empty input works','most_common_words([]) == []']],'Find the maximum count, then keep every key with that count.'),
 project:P('A Word Frequency Report','Summarize words from a short text you invent.',['Normalize case and split the text into words.','Count words with Counter and show the most frequent ones.','Use sorted output and define how you handle empty text.'],'from collections import Counter\ntext = "blue river blue sky"\n# Clean, count, and report.\n',['Try repeated words and mixed case.','Try a tie for the highest count.','Try empty text.'],['Remove simple punctuation with replace().','Calculate average word length with statistics.'],'text.lower().split() gives lowercase words separated by whitespace.','How will you handle punctuation and ties?'),
