 parts:[['with open(','Manage a file','The with block handles closing the file.'],['"notes.txt", "w",','Path and mode','Use a relative path in the practice folder. Mode w replaces the file contents.'],[' encoding="utf-8") as file:','Text encoding and name','Inside the block, file refers to the open file object.']],
 walk:[['with open("notes.txt", "w", encoding="utf-8") as file:','Open a new file for writing in this run’s practice folder.'],['    file.write("Read\\nPractise\\n")','Write two lines. \\n is a newline character in the text.'],['with open("notes.txt", "r", encoding="utf-8") as file:','Reopen the file for reading after the write block has closed it.'],['    text = file.read()','Read the complete text into a string.'],['print(text.strip())','Display it without an extra trailing blank line.']],change:'Append a third line using mode "a". Inspect and download notes.txt after the run.',
