 predict:prediction('with open("a.txt", "w", encoding="utf-8") as f:\n    f.write("one")\nwith open("a.txt", "a", encoding="utf-8") as f:\n    f.write("two")\nwith open("a.txt", encoding="utf-8") as f:\n    print(f.read())',['two','one\ntwo','onetwo'],2,['Append does not replace the original text.','write() does not add a newline automatically.','The second write adds text directly after the first.']),
 build:T('build','Write Two Lines','Create notes.txt containing Hello and Python on separate lines, with a newline after each.','# Write notes.txt with a with block.\n','with open("notes.txt", "w", encoding="utf-8") as file:\n    file.write("Hello\\nPython\\n")',[['The file has the requested text','open("notes.txt",encoding="utf-8").read() == "Hello\\nPython\\n"']],'Use "\\n" inside a string for a newline.'),
 repair:T('repair','Keep Earlier Text','The second write should append, so both first and second remain on separate lines.','with open("log.txt", "w", encoding="utf-8") as f:\n    f.write("first\\n")\nwith open("log.txt", "w", encoding="utf-8") as f:\n    f.write("second\\n")','with open("log.txt", "w", encoding="utf-8") as f:\n    f.write("first\\n")\nwith open("log.txt", "a", encoding="utf-8") as f:\n    f.write("second\\n")',[['Both lines are kept','open("log.txt",encoding="utf-8").read() == "first\\nsecond\\n"']],'Change only the second mode from w to a.'),
 practice:[T('save','Save a List of Lines','Write save_lines(path, lines). Write each string followed by a newline. An empty list must create an empty file.','def save_lines(path, lines):\n    pass','def save_lines(path, lines):\n    with open(path, "w", encoding="utf-8") as file:\n        for line in lines:\n            file.write(line + "\\n")',[['Lines are saved with newlines','(save_lines("check.txt",["a","b"]),open("check.txt",encoding="utf-8").read())[1] == "a\\nb\\n"'],['An empty file can be written','(save_lines("empty.txt",[]),open("empty.txt",encoding="utf-8").read())[1] == ""']],'Use a loop inside the with block.'),T('read','Read Non-Blank Lines','Write read_nonblank(path). Return stripped non-empty lines in order.','def read_nonblank(path):\n    pass','def read_nonblank(path):\n    with open(path, encoding="utf-8") as file:\n        return [line.strip() for line in file if line.strip()]',[['Spaces and blank lines are handled','_write_text("input.txt"," a \\n\\n b\\n") and read_nonblank("input.txt") == ["a","b"]'],['Empty input works','_write_text("input.txt","") and read_nonblank("input.txt") == []']],'An open text file can be used directly in a loop or comprehension.')],
 homework:T('hw','Copy Text in Uppercase','Write copy_upper(source, target). Read source and write an uppercase copy to target. Preserve newlines and leave source unchanged.','def copy_upper(source, target):\n    pass','def copy_upper(source, target):\n    with open(source, encoding="utf-8") as file:\n        text = file.read()\n    with open(target, "w", encoding="utf-8") as file:\n        file.write(text.upper())',[['The target contains uppercase text','_write_text("source.txt","Hello\\nworld\\n") and (copy_upper("source.txt","target.txt"),open("target.txt",encoding="utf-8").read())[1] == "HELLO\\nWORLD\\n"'],['The source is unchanged','open("source.txt",encoding="utf-8").read() == "Hello\\nworld\\n"'],['Empty text works','_write_text("blank.txt","") and (copy_upper("blank.txt","out.txt"),open("out.txt",encoding="utf-8").read())[1] == ""']],'str.upper() returns an uppercase copy. Use separate read and write blocks.'),
 project:P('A Text Report Writer','Turn a sample journal into a summary file.',['Create a sample text file at the start of the program.','Read its non-blank lines and calculate a useful count.','Write a separate report file and download it after running.'],'with open("journal.txt", "w", encoding="utf-8") as file:\n    file.write("Read a chapter\\nPractise Python\\n")\n\n# Read the journal and write report.txt.\n',['Try an empty journal.','Try blank lines between entries.','Run again and check that your code creates its required input file.'],['Include word counts.','Use append mode for a second report section.'],'Each run starts fresh. Include file setup and inspect Files from This Run.','What useful facts will your report contain?'),
 quiz:Q('What does opening an existing file in mode "w" do?',['Adds text after existing contents','Replaces existing contents'],1,'Write mode truncates the file. Use append mode when you want to keep existing contents.'),words:[['context manager','An object used by with to manage setup and cleanup.'],['encoding','The rule for converting text to and from bytes.'],['append mode','A file mode that adds new text at the end.']],recap:['Choose read, write, or append mode deliberately.','Use with and specify a text encoding.','Files here last for one run; download outputs you want to keep.'],reflection:'Why does your function open the source and target in different modes?'
