 return {...lesson,course:'intermediate',index,section:intermediateSections.find(s=>s.lessons.includes(lesson.id)),minutes:30,input:'',code:lesson.walk.map(line=>line[0]).join('\n'),project,slides,prompts:[lesson.project.extras[0],lesson.project.extras[1],'Try another input and explain what changes.']};
